import XCTest
@testable import BioCueCore

/// Checks the Swift port against outputs generated by the real Android Kotlin code
/// (tools/gen_parity_fixtures.sh -> ParityFixtures.swift).
final class ParityTests: XCTestCase {

    // MARK: fixture schema
    private struct File: Decodable {
        let scoring: [Scoring]
        let pipeline: [Pipeline]
        let clusterer: [Clusterer]
        let resolve: [Resolve]
        let eventTypes: [TypeCase]
    }
    private struct Scoring: Decodable {
        let hr, rmssd, acc, rep, slope: Double
        let off, ex: Bool
        let bHr, bHrStd, bHrv, bHrvStd: Double
        let sleep: Bool
        let score: Double
        let tier, pct: Int
    }
    private struct LatestJSON: Decodable { let id: String; let start: Int64; let end: Int64? }
    private struct ActionJSON: Decodable { let t: String; let start: Int64?; let id: String?; let end: Int64? }
    private struct Pipeline: Decodable {
        let ts: Int64
        let hr, rmssd, acc, rep, slope: Double
        let off: Bool
        let now: Int64
        let latest: LatestJSON?
        let score: Double
        let tier: Int
        let actions: [ActionJSON]
    }
    private struct EventJSON: Decodable { let id: String; let start: Int64; let end: Int64? }
    private struct ClusterJSON: Decodable { let start: Int64; let end: Int64?; let ids: [String] }
    private struct Clusterer: Decodable { let events: [EventJSON]; let clusters: [ClusterJSON] }
    private struct Resolve: Decodable { let current, incoming, label: String; let resolved: Bool }
    private struct TypeCase: Decodable { let label, icon, color: String }

    private func load() throws -> File {
        try JSONDecoder().decode(File.self, from: Data(ParityFixtures.json.utf8))
    }

    // MARK: tests

    func testScoringMatchesKotlinForEveryCase() throws {
        let cases = try load().scoring
        XCTAssertGreaterThan(cases.count, 100)
        for (i, c) in cases.enumerated() {
            let w = SensorWindow(timestamp: 0, hrMean: c.hr, rmssd: c.rmssd, accMag: c.acc, repetitiveness: c.rep,
                                 hrSlope: c.slope, isOffBody: c.off, isExercising: c.ex)
            let b = Baseline(hourOfDay: 12, hrMean: c.bHr, hrStd: c.bHrStd, hrvMean: c.bHrv, hrvStd: c.bHrvStd)
            let score = ScoringEngine().computeRuleBasedScore(window: w, baseline: b, poorSleepFlag: c.sleep)
            XCTAssertEqual(score, c.score, accuracy: 1e-9, "scoring case \(i)")
            XCTAssertEqual(DetectionPipeline.tierFor(c.score), c.tier, "tier case \(i)")
            XCTAssertEqual(DetectionPipeline.stressPercent(c.score), c.pct, "pct case \(i)")
        }
    }

    func testPipelineDecisionsMatchKotlinForEveryCase() throws {
        let cases = try load().pipeline
        XCTAssertGreaterThan(cases.count, 100)
        for (i, c) in cases.enumerated() {
            let w = SensorWindow(timestamp: c.ts, hrMean: c.hr, rmssd: c.rmssd, accMag: c.acc, repetitiveness: c.rep,
                                 hrSlope: c.slope, isOffBody: c.off, isExercising: false)
            let latest = c.latest.map { LatestEvent(id: $0.id, startTime: $0.start, endTime: $0.end) }
            let d = DetectionPipeline.decide(window: w, baseline: .appDefault, latestEvent: latest, nowMs: c.now)
            XCTAssertEqual(d.score, c.score, accuracy: 1e-9, "score \(i)")
            XCTAssertEqual(d.tier, c.tier, "tier \(i)")
            let expected: [PipelineAction] = c.actions.map { a in
                a.t == "create" ? .createAutoEvent(startTime: a.start!) : .closeEvent(eventId: a.id!, endTime: a.end!)
            }
            XCTAssertEqual(d.actions, expected, "actions \(i)")
        }
    }

    func testClustererMatchesKotlinIncludingTiesAndOpenEndedEvents() throws {
        let cases = try load().clusterer
        XCTAssertGreaterThan(cases.count, 30)
        for (i, c) in cases.enumerated() {
            let events = c.events.map {
                StressEvent(id: $0.id, userId: "u", startTime: $0.start, endTime: $0.end,
                            triggerType: "AUTO", label: "NONE", isResolved: false)
            }
            let got = EventClusterer.cluster(events)
            XCTAssertEqual(got.count, c.clusters.count, "cluster count \(i)")
            for (g, e) in zip(got, c.clusters) {
                XCTAssertEqual(g.startTime, e.start, "start \(i)")
                XCTAssertEqual(g.endTime, e.end, "end \(i)")
                XCTAssertEqual(g.events.map { $0.id }, e.ids, "ids/order \(i)")
            }
        }
    }

    func testResolveLogicMatchesKotlin() throws {
        let cases = try load().resolve
        XCTAssertEqual(cases.count, 45)
        for c in cases {
            let r = ResolveLogic.processResolution(currentLabel: c.current, newLabelOrContext: c.incoming)
            XCTAssertEqual(r.label, c.label, "\(c.current) + \(c.incoming)")
            XCTAssertEqual(r.resolved, c.resolved, "\(c.current) + \(c.incoming)")
        }
    }

    func testEventTypeIconsAndColorsMatchKotlin() throws {
        for c in try load().eventTypes {
            XCTAssertEqual(EventTypes.icon(forLabel: c.label), c.icon, "icon for '\(c.label)'")
            XCTAssertEqual(EventTypes.colorHex(forLabel: c.label), c.color, "color for '\(c.label)'")
        }
    }

    func testFixturesActuallyExerciseEveryBranch() throws {
        // Guards against a regenerated fixture set that silently stops covering something.
        let f = try load()
        XCTAssertEqual(Set(f.pipeline.map { $0.tier }), [0, 1, 2])
        XCTAssertTrue(f.pipeline.contains { $0.actions.contains { $0.t == "create" } })
        XCTAssertTrue(f.pipeline.contains { $0.actions.contains { $0.t == "close" } })
        XCTAssertTrue(f.scoring.contains { $0.off })
        XCTAssertTrue(f.scoring.contains { $0.bHrStd == 0 })
        XCTAssertTrue(f.clusterer.contains { $0.clusters.contains { $0.end == nil } })
    }
}
